#: 与 service._ONT_TABLES_SQL 对齐：代码里用到的每一张 ai_ont_* 表都必须在此有对应建表语句
def missing_from_ddl(used: set[str]) -> list[str]:
    """返回「代码引用但 DDL 未声明」的表名（供回归测试断言为空）。"""
    return sorted(used - set(ONT_DDL))
